parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "respuesta_al_cliente": {
      "type": "string",
      "description": "Mensaje final que se le muestra al cliente en el chat. Español rioplatense, máximo 6 líneas, sin lenguaje inclusivo."
    },
    "tipo_consulta": {
      "type": "string",
      "enum": [
        "reclamo",
        "seguimiento de una compra",
        "consulta precio o stock",
        "consulta técnica sobre el producto",
        "otro"
      ],
      "description": "Clasificación del motivo principal de la consulta del cliente."
    },
    "categoria_productos": {
      "type": "string",
      "enum": ["Cortadoras", "Repuestos", "N/A"],
      "description": "Categoría del catálogo a la que pertenecen los productos de la consulta. Usar N/A si la consulta no involucra productos."
    },
    "productos_relacionados": {
      "type": "array",
      "description": "Productos del catálogo mencionados o consultados. Lista vacía si no hay ninguno. Solo productos devueltos por las herramientas de catálogo, nunca inventados.",
      "items": {
        "type": "object",
        "properties": {
          "sku": { "type": "string", "description": "SKU exacto del catálogo, por ejemplo COR-001 o REP-001." },
          "nombre": { "type": "string", "description": "Nombre del producto tal como figura en el catálogo." }
        },
        "required": ["sku", "nombre"],
        "additionalProperties": false
      }
    },
    "resultado_interaccion": {
      "type": "string",
      "enum": [
        "reclamo derivado a equipo correspondiente",
        "reclamo resuelto",
        "consulta respondida",
        "consulta derivada a equipo correspondiente",
        "venta concretada"
      ],
      "description": "Resultado de esta interacción. Elegir solo un valor que haya ocurrido realmente en la conversación."
    }
  },
  "required": [
    "respuesta_al_cliente",
    "tipo_consulta",
    "categoria_productos",
    "productos_relacionados",
    "resultado_interaccion"
  ],
  "additionalProperties": false
}

